1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	import java.util.regex.Pattern;
6	
7	import net.officefloor.plugin.variable.Out;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.samples.petclinic.rest.escalation.RequiredFieldsException;
10	import org.springframework.web.bind.annotation.RequestBody;
11	
12	/**
13	 * Rejects a create request that is missing or blank in any required owner field,
14	 * before {@link BuildOwner} runs. The names of the offending fields are reported
15	 * as a 400 by {@link org.springframework.samples.petclinic.rest.escalation.RequiredFieldsExceptionHandler}.
16	 *
17	 * <p>This is a manual guard rather than {@code @Valid} so that a missing or blank
18	 * required field yields the {@code errors} field-name array this endpoint promises,
19	 * instead of the generic schema-validation problem detail.
20	 */
21	public class RequireOwnerFields {
22	
23	    /** A pragmatic syntactic email check: a local part, an '@', and a dotted domain,
24	     *  none containing whitespace or a second '@'. */
25	    private static final Pattern EMAIL_PATTERN =
26	            Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
27	
28	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
29	            throws RequiredFieldsException {
30	        List<String> errors = new ArrayList<>();
31	        checkField("firstName", request.getFirstName(), errors);
32	        checkField("lastName", request.getLastName(), errors);
33	        // Normalize the address before the required-field check, so an address that is
34	        // blank after normalization is rejected and the stored/returned value is canonical.
35	        String address = AddressNormalizer.normalize(request.getAddress());
36	        if (address.isEmpty()) {
37	            errors.add("address");
38	        }
39	        else {
40	            request.setAddress(address);
41	        }
42	        checkField("city", request.getCity(), errors);
43	        checkField("telephone", request.getTelephone(), errors);
44	        if (!errors.isEmpty()) {
45	            throw new RequiredFieldsException(errors);
46	        }
47	        // Normalize the telephone to E.164 form; reject when it cannot form a valid one.
48	        String telephone = Telephones.toE164(request.getTelephone());
49	        if (telephone == null) {
50	            throw new RequiredFieldsException(List.of("telephone"));
51	        }
52	        request.setTelephone(telephone);
53	        // Email is optional; when present it must be syntactically valid and is
54	        // stored and returned lower-cased.
55	        String email = request.getEmail();
56	        if (email != null && !email.isBlank()) {
57	            if (!EMAIL_PATTERN.matcher(email).matches()) {
58	                throw new RequiredFieldsException(List.of("email"));
59	            }
60	            request.setEmail(email.toLowerCase());
61	        }
62	        validated.set(request);
63	    }
64	
65	    private static void checkField(String name, String value, List<String> errors) {
66	        if (value == null || value.isBlank()) {
67	            errors.add(name);
68	        }
69	    }
70	}
