1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.repository.OwnerRepository;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	
12	/**
13	 * When the request opts into sharing a household ({@code sharesHousehold} true), assigns a
14	 * stable {@code householdId} derived from the normalized last name and address, so every
15	 * owner living together at the same address shares one identifier. Existing owners of the
16	 * same household that do not yet carry an id are back-filled with the same value, so both
17	 * the joining owner and the owner already at that address end up sharing it. Normalization
18	 * matches {@link RequireUniqueHousehold} (lower-cased, trimmed, whitespace collapsed).
19	 */
20	public class AssignHousehold {
21	
22	    public void service(@Val OwnerFieldsDto request, @Val Owner owner,
23	            OwnerRepository ownerRepository) {
24	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
25	            return;
26	        }
27	        String lastName = normalize(owner.getLastName());
28	        String address = AddressNormalizer.normalize(owner.getAddress());
29	        String householdId = hash(lastName + "|" + address);
30	        owner.setHouseholdId(householdId);
31	        // Back-fill existing household members so both sides share the identifier.
32	        for (Owner existing : ownerRepository.findAll()) {
33	            if (existing.getHouseholdId() == null
34	                    && lastName.equals(normalize(existing.getLastName()))
35	                    && address.equals(AddressNormalizer.normalize(existing.getAddress()))) {
36	                existing.setHouseholdId(householdId);
37	                ownerRepository.save(existing);
38	            }
39	        }
40	    }
41	
42	    /** Lower-case, trim, and collapse runs of whitespace to a single space. */
43	    private static String normalize(String value) {
44	        if (value == null) {
45	            return "";
46	        }
47	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
48	    }
49	
50	    /** Stable 16-hex-character (upper-case) prefix of the SHA-256 of the household key. */
51	    private static String hash(String value) {
52	        try {
53	            byte[] digest = MessageDigest.getInstance("SHA-256")
54	                    .digest(value.getBytes(StandardCharsets.UTF_8));
55	            StringBuilder sb = new StringBuilder();
56	            for (int i = 0; i < 8; i++) {
57	                sb.append(String.format("%02X", digest[i]));
58	            }
59	            return sb.toString();
60	        }
61	        catch (NoSuchAlgorithmException e) {
62	            throw new IllegalStateException("SHA-256 not available", e);
63	        }
64	    }
65	}
