1	package org.springframework.samples.petclinic.rest.escalation;
2	
3	/**
4	 * Thrown when a create request supplies a telephone whose normalized form is already
5	 * used by an existing owner. Handled by {@link DuplicateTelephoneExceptionHandler},
6	 * which responds 409 Conflict.
7	 */
8	public class DuplicateTelephoneException extends Exception {
9	
